const channels = ['Google Ads', 'Facebook', 'Instagram', 'LinkedIn', 'Email'];
const months = ['January', 'February', 'March', 'April', 'May', 'June'];
const campaignNames = {
  'Google Ads': ['Search - Brand', 'Search - Generic', 'Shopping Campaign'],
  'Facebook': ['Prospecting Q1', 'Retargeting - Cart', 'Lookalike Audiences'],
  'Instagram': ['Stories - Product', 'Reels Campaign', 'Feed - Lifestyle'],
  'LinkedIn': ['B2B Awareness', 'Lead Gen Form', 'Sponsored Content'],
  'Email': ['Welcome Series', 'Win-Back Campaign', 'Weekly Newsletter']
};

const rows = [];

for (const month of months) {
  for (const channel of channels) {
    const campaigns = campaignNames[channel];
    for (const campaign of campaigns) {
      const spend = parseFloat((Math.random() * 5000 + 500).toFixed(2));
      const impressions = Math.floor(Math.random() * 200000 + 10000);
      const clicks = Math.floor(impressions * (Math.random() * 0.05 + 0.01));
      const conversions = Math.floor(clicks * (Math.random() * 0.1 + 0.02));
      const revenue = parseFloat((conversions * (Math.random() * 150 + 50)).toFixed(2));

      rows.push({
        campaign_name: campaign,
        channel,
        month,
        spend,
        impressions,
        clicks,
        conversions,
        revenue
      });
    }
  }
}

return [{ json: { data: rows, count: rows.length } }];
